import { Ledgerly } from '@ledgerly/node';

const ledgerly = new Ledgerly(process.env.LEDGERLY_KEY);

const invoice = await ledgerly.invoices.create({
  customer: 'cus_8fK2',
  currency: 'eur',
  lines: [{ description: 'Pro plan, October', amount: 4900 }],
  send: true,
});

console.log(invoice.status);
